root=Path.cwd();cache=root/'.cache/three-host-cleanup-milestone';out=root/'implementation/2026-10-12-three-host-cleanup'
assert not out.exists(),'Refusing to overwrite immutable checkpoint'
commands=json.loads((cache/'commands.json').read_text());assert len(commands)==27 and all(c['exitCode']==0 for c in commands)
